import{_ as t,o as a,c as n,ah as s}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Learner journey","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/learner-journey.md","filePath":"src/en/guide/learner-journey.md"}'),r={name:"en/guide/learner-journey.md"};function i(o,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="learner-journey" tabindex="-1">Learner journey <a class="header-anchor" href="#learner-journey" aria-label="Permalink to &quot;Learner journey&quot;">​</a></h1><p>From candidature to Parcours Canopé, this is a learner&#39;s full path through Kura. Every step is triggered by an identified actor and leaves a trace.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NextBoxx website</span></span>
<span class="line"><span>    │  submission (API)</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Candidature ──► Interview ──► QCM test ──► Decision</span></span>
<span class="line"><span>                                            │ admitted</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                                        Enrolment</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>                    consents ──► Agreement ──► 1st instalment</span></span>
<span class="line"><span>                                            │           │</span></span>
<span class="line"><span>                                            │           ├─► Sève account</span></span>
<span class="line"><span>                                            │           └─► welcome booklet</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                              Training (Sève) · attendance · grades</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>                      mid-course (40%) ──► balance (30%)</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                                 Certificate ──► Canopé</span></span></code></pre></div><h2 id="_1-candidature-submission" tabindex="-1">1. Candidature submission <a class="header-anchor" href="#_1-candidature-submission" aria-label="Permalink to &quot;1. Candidature submission&quot;">​</a></h2><p>The candidate chooses a published programme and a format on the NextBoxx website, then submits their file (motivation, optional documents, minor flag, optional referral code). The website sends it to Kura through the API.</p><p>Kura creates or reuses the account, grants the <strong>Candidate</strong> role and opens the candidature. The candidate receives an acknowledgement with a link to choose a password if the account is new.</p><p>One candidature in progress per account, whatever the programme. After a refusal, a new submission is possible after <strong>7 days</strong>, attached to the same account and linked to the previous one.</p><h2 id="_2-interview" tabindex="-1">2. Interview <a class="header-anchor" href="#_2-interview" aria-label="Permalink to &quot;2. Interview&quot;">​</a></h2><p>An Admissions Advisor takes the file from the shared queue and becomes responsible for it. The interview must be held within <strong>5 business days</strong>; only the responsible advisor closes it, with an internal report. Closing opens the test.</p><p>Business days run Monday to Friday, excluding public holidays entered by the Administrator. A daily task reminds once about each overdue step.</p><h2 id="_3-admission-test" tabindex="-1">3. Admission test <a class="header-anchor" href="#_3-admission-test" aria-label="Permalink to &quot;3. Admission test&quot;">​</a></h2><p>The link is sent when the interview closes if the programme&#39;s QCM bank is validated. Characteristics:</p><ul><li>single-use link, no sign-in, <strong>48-hour</strong> window to start;</li><li><strong>2 attempts</strong>, <strong>45 minutes</strong> each from opening;</li><li><strong>10 questions</strong> drawn from the 20 validated ones; the second attempt excludes those from the first;</li><li>score shown on submission, <strong>indicative 60% pass mark</strong> (6/10);</li><li>a successful attempt closes the test; otherwise it closes after the second attempt.</li></ul><p>The score is indicative: the file goes to decision whatever the result. If the link expires, the Advisor is reminded once, then sends a new link or closes the test.</p><h2 id="_4-decision" tabindex="-1">4. Decision <a class="header-anchor" href="#_4-decision" aria-label="Permalink to &quot;4. Decision&quot;">​</a></h2><p>The responsible advisor makes a <strong>reasoned decision within 3 business days</strong> after the test. The reason stays internal; the candidate is notified by email.</p><table tabindex="0"><thead><tr><th>Decision</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Admitted</strong></td><td>Learner role, enrolment created, cohort chosen or placement later</td></tr><tr><td><strong>Refused</strong></td><td>File closed, no payment or Sève access; kept 12 months then anonymised</td></tr></tbody></table><p>The decision letter is generated, attached to the email and downloadable from “My candidatures”.</p><h2 id="_5-enrolment-consents-and-agreement" tabindex="-1">5. Enrolment, consents and agreement <a class="header-anchor" href="#_5-enrolment-consents-and-agreement" aria-label="Permalink to &quot;5. Enrolment, consents and agreement&quot;">​</a></h2><p>The enrolment is created on admission, with the status <strong>pending signature</strong>. The Advisor chooses an open or confirmed cohort that has not started yet, with a seat and a price for the format; otherwise the Coordinator places the learner before signature.</p><p>Before signing, the learner:</p><ul><li>confirms or changes their <strong>format</strong> among those priced for the cohort;</li><li>gives <strong>two separate consents</strong>: pedagogical reuse of the tutored project and image rights;</li><li>for a minor, has their <strong>legal representative</strong> sign through a 7-day email link, without an account.</li></ul><p>The Agreement is signed with a <strong>6-digit code</strong> received by email: valid 15 minutes, 5 attempts, single use. The edPage countersignature is automatic or manual according to the Administrator&#39;s setting. It freezes the format, cohort and price, activates the enrolment and produces the sealed PDF <code>CONV-NB-YYYY-XXX</code>.</p><h2 id="_6-first-instalment-and-seve-access" tabindex="-1">6. First instalment and Sève access <a class="header-anchor" href="#_6-first-instalment-and-seve-access" aria-label="Permalink to &quot;6. First instalment and Sève access&quot;">​</a></h2><p>After countersignature, the first invoice (30%) is issued. As soon as <strong>all shares</strong> of that instalment are paid — learner and funder — Kura:</p><ul><li>provisions the Sève account (SSO, no Moodle password);</li><li>enrols the learner in their cohort&#39;s course;</li><li>generates and sends the <strong>welcome booklet</strong> <code>LA-NB-YYYY-XXX</code>.</li></ul><p>A suspension or reactivation is mirrored in Sève. A cohort change replaces the agreement and produces a new booklet.</p><h2 id="_7-training-attendance-and-results" tabindex="-1">7. Training, attendance and results <a class="header-anchor" href="#_7-training-attendance-and-results" aria-label="Permalink to &quot;7. Training, attendance and results&quot;">​</a></h2><p>The learner follows their training on Sève. Virtual session attendance and per-block grades flow back into Kura every hour. In-person attendance is entered by a Lead Trainer.</p><ul><li>Alert to the Coordinator and the learner above <strong>30% absence</strong>.</li><li>Grades out of 20 per block; weighted average by block duration.</li><li>Retake possible for a block below 10/20, 15 days after the last grade, at most twice.</li><li>Tutored project, defence and internship are entered by the Coordinator; these grades stay out of the average.</li></ul><h2 id="_8-billing-the-journey" tabindex="-1">8. Billing the journey <a class="header-anchor" href="#_8-billing-the-journey" aria-label="Permalink to &quot;8. Billing the journey&quot;">​</a></h2><p>The 40% (mid-course) and 30% (end) instalments are issued as they fall due, 15 days before their due date, with reminders at D-15, D-7 and D-1. The unpaid timeline is detailed in <a href="/kura-guide/en/guide/billing.html">Billing</a>.</p><h2 id="_9-certificate-and-parcours-canope" tabindex="-1">9. Certificate and Parcours Canopé <a class="header-anchor" href="#_9-certificate-and-parcours-canope" aria-label="Permalink to &quot;9. Certificate and Parcours Canopé&quot;">​</a></h2><p>The certificate is delivered when <strong>all four conditions</strong> are met:</p><ol><li>average ≥ 10/20;</li><li>no block below 8/20;</li><li>defence validated;</li><li>balance fully paid.</li></ol><p>No condition compensates another. The certificate <code>CERT-NB-YYYY-XXX</code> is frozen, sealed with a SHA-256 fingerprint and signed in the name of the jury president. Delivery completes the enrolment, removes the learner from their cohort course, moves the account to the <strong>Canopé</strong> status and enrols it in Parcours Canopé.</p><p>On interruption with at least one validated block, the Coordinator delivers a <strong>partial attestation</strong> <code>ATP-NB-YYYY-XXX</code>, never a partial certificate. A <strong>transcript of competences</strong> accompanies the certificate or attestation.</p><h2 id="what-the-learner-sees" tabindex="-1">What the learner sees <a class="header-anchor" href="#what-the-learner-sees" aria-label="Permalink to &quot;What the learner sees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th></tr></thead><tbody><tr><td>My candidatures</td><td>Steps, decision, decision letter</td></tr><tr><td>My enrolment</td><td>Cohort, format, price, agreement, consents</td></tr><tr><td>My documents</td><td>Agreements, booklet, invoices, credit notes, certificate, attestation, transcript</td></tr><tr><td>My invoices</td><td>Due dates, payments, PDFs</td></tr><tr><td>My roles</td><td>Role requests and status</td></tr><tr><td>My events</td><td>Event registrations</td></tr><tr><td>My projects / My funding</td><td>L&#39;Éclosion and event contributions, depending on roles</td></tr></tbody></table>`,39)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
